def sign_delegated_user(
    *,
    user_issuer: str,
    user_subject: str,
    authenticated_at: int,
    private_key: Ed25519PrivateKey,
    issuer: str,
    audience: str,
    key_id: str,
    request_body: dict[str, Any],
    now: int | None = None,
    lifetime_seconds: int = 60,
) -> str:
    """Sign exact request bytes using verified upstream authentication time only."""
    current = int(time.time()) if now is None else now
    if (
        type(authenticated_at) is not int
        or authenticated_at < 0
        or authenticated_at > current + 30
        or current - authenticated_at > 300
        or type(lifetime_seconds) is not int
        or not 1 <= lifetime_seconds <= 60
        or not issuer
        or not audience
        or not key_id
        or not user_issuer
        or not 1 <= len(user_subject) <= 128
    ):
        raise ValueError("delegated_user_identity_unavailable")
    header = {"alg": "EdDSA", "kid": key_id, "typ": "JWT"}
    claims = {
        "iss": issuer,
        "aud": audience,
        "sub": f"{user_issuer}|{user_subject}",
        "user_issuer": user_issuer,
        "user_subject": user_subject,
        "iat": current,
        "exp": current + lifetime_seconds,
        "auth_time": authenticated_at,
        "jti": str(uuid4()),
        "request_sha256": sha256(canonical_bytes(request_body)).hexdigest(),
        "purpose": request_body.get("purpose"),
        "destination_application_id": request_body.get("destination_application_id"),
    }

    def encode(value: bytes) -> str:
        return base64.urlsafe_b64encode(value).rstrip(b"=").decode("ascii")

    header_segment = encode(json.dumps(header, separators=(",", ":")).encode())
    claims_segment = encode(json.dumps(claims, separators=(",", ":")).encode())
    signing_input = f"{header_segment}.{claims_segment}"
    return f"{signing_input}.{encode(private_key.sign(signing_input.encode('ascii')))}"


@dataclass(frozen=True)
class VerifiedDelegatedUser:
    issuer: str
    subject: str
    authenticated_at: int


def verify_delegated_user(
    assertion: str,
    request_body: dict[str, Any],
    *,
    public_key: Ed25519PublicKey,
    issuer: str,
    audience: str,
    key_id: str,
    now: int,
    allowed_user_issuers: frozenset[str],
    max_auth_age_seconds: int = 300,
) -> VerifiedDelegatedUser:
    """Verify the existing request-bound PAI assertion; transport auth is separate."""
    try:
        if not assertion or len(assertion) > 8192:
            raise ValueError
        segments = assertion.split(".")
        if len(segments) != 3:
            raise ValueError
        decoded = []
        alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"
        for segment in segments:
            if not segment or any(c not in alphabet for c in segment):
                raise ValueError
            decoded.append(
                base64.urlsafe_b64decode(segment + "=" * (-len(segment) % 4))
            )
        public_key.verify(decoded[2], f"{segments[0]}.{segments[1]}".encode("ascii"))
        header, claims = json.loads(decoded[0]), json.loads(decoded[1])
        required = {
            "iss",
            "aud",
            "sub",
            "user_issuer",
            "user_subject",
            "iat",
            "exp",
            "auth_time",
            "jti",
            "request_sha256",
            "purpose",
            "destination_application_id",
        }
        if not isinstance(claims, dict):
            raise TypeError
        if (
            header != {"alg": "EdDSA", "kid": key_id, "typ": "JWT"}
            or set(claims) != required
        ):
            raise ValueError
        iat, exp, auth_time = (claims[name] for name in ("iat", "exp", "auth_time"))
        if any(type(value) is not int for value in (iat, exp, auth_time)):
            raise ValueError
        user_issuer, subject = claims["user_issuer"], claims["user_subject"]
        if (
            claims["iss"] != issuer
            or claims["aud"] != audience
            or user_issuer not in allowed_user_issuers
            or not isinstance(subject, str)
            or not 1 <= len(subject) <= 128
            or claims["sub"] != f"{user_issuer}|{subject}"
            or iat > now + 30
            or not now < exp <= iat + 60
            or exp <= iat
            or now - iat > 60
            or auth_time < 0
            or auth_time > now + 30
            or now - auth_time > max_auth_age_seconds
            or claims["request_sha256"]
            != sha256(canonical_bytes(request_body)).hexdigest()
            or claims["purpose"] != request_body.get("purpose")
            or claims["destination_application_id"]
            != request_body.get("destination_application_id")
        ):
            raise ValueError
        UUID(claims["jti"])
        return VerifiedDelegatedUser(user_issuer, subject, auth_time)
    except (
        ValueError,
        TypeError,
        KeyError,
        InvalidSignature,
        AttributeError,
        RecursionError,
    ) as error:
        raise ValueError("delegated_user_invalid") from error


